static inline const char *p7580_js_status_name(uint32_t status)
{
	unsigned int i;

	/* kbase jm_hw.h slot states, so a TIMEOUT line says what the JM
	 * actually did: 0x00 never started, 0x01 finished, 0x08 running. */
	switch (status) {
	case 0x00u:
		return "NOT_STARTED/OK";
	case 0x01u:
		return "DONE";
	case 0x02u:
		return "INTERRUPTED";
	case 0x03u:
		return "STOPPED";
	case 0x04u:
		return "TERMINATED";
	case 0x08u:
		return "ACTIVE";
	}

	for (i = 0; i < sizeof(p7580_js_faults) /
			sizeof(p7580_js_faults[0]); i++) {
		if (p7580_js_faults[i].code == status)
			return p7580_js_faults[i].name;
	}
	return (status < 0x40u) ? "NO_EXCEPTION" : "RESERVED_FAULT";


